'use strict';

class LookupValue {
  constructor(id, label, tags = []) {
    if (typeof id !== 'string' || typeof label !== 'string' ||
        !Array.isArray(tags) || tags.some((tag) => typeof tag !== 'string')) {
      throw new TypeError('invalid lookup value');
    }
    this.id = id;
    this.label = label;
    this.tags = Object.freeze(tags.slice());
  }

  describe() {
    return this.id + ': ' + this.label;
  }
}

class ProjectionValue extends LookupValue {}

Object.defineProperty(ProjectionValue, 'metadata', {
  value: Object.freeze({ namespace: 'ledger', collection: 'projected_codes' }),
  enumerable: true,
  writable: false,
  configurable: false
});

module.exports = { LookupValue, ProjectionValue };

