'use strict';
const assert = require('node:assert/strict');
const api = require('./solution');
assert.deepEqual(Object.keys(api).sort(), ['LookupValue', 'ProjectionValue']);
const { LookupValue, ProjectionValue } = api;

const defaulted = new LookupValue('id', 'Label');
assert.equal(defaulted.id, 'id');
assert.equal(defaulted.label, 'Label');
assert.deepEqual(defaulted.tags, []);
assert.equal(Object.isFrozen(defaulted.tags), true);
assert.equal(defaulted.describe(), 'id: Label');

const callerTags = ['one', 'two'];
const value = new LookupValue('', '', callerTags);
assert.deepEqual(value.tags, ['one', 'two']);
assert.notStrictEqual(value.tags, callerTags);
assert.equal(Object.isFrozen(value.tags), true);
callerTags.push('three');
assert.deepEqual(value.tags, ['one', 'two']);
assert.throws(() => value.tags.push('x'), TypeError);

const other = new LookupValue('other', 'Other');
assert.notStrictEqual(other.tags, defaulted.tags);
const projected = new ProjectionValue('p1', 'Projection', ['tag']);
assert.equal(projected instanceof ProjectionValue, true);
assert.equal(projected instanceof LookupValue, true);
assert.equal(projected.describe(), 'p1: Projection');
assert.deepEqual(projected.tags, ['tag']);
assert.equal(Object.isFrozen(projected.tags), true);
assert.deepEqual(ProjectionValue.metadata, { namespace: 'ledger', collection: 'projection_codes' });
assert.deepEqual(Object.keys(ProjectionValue.metadata).sort(), ['collection', 'namespace']);
assert.equal(Object.isFrozen(ProjectionValue.metadata), true);
assert.throws(() => { ProjectionValue.metadata.namespace = 'changed'; }, TypeError);

for (const args of [[1, 'label'], ['id', null], ['id', 'label', null], ['id', 'label', 'tag'], ['id', 'label', ['ok', 2]]]) {
  assert.throws(() => new LookupValue(...args), TypeError);
  assert.throws(() => new ProjectionValue(...args), TypeError);
}

